// Normaliza o payload do formulário, gera o protocolo e prepara DUAS versões da
// descrição: a íntegra, que segue para o canal do time responsável, e a sanitizada,
// que é a única enviada ao provedor de LLM.
const body = $json.body || {};

const obrigatorios = ['nome_cliente', 'cpf', 'descricao_caso'];
const faltando = obrigatorios.filter((c) => !body[c]);
if (faltando.length) {
  throw new Error('Campos obrigatorios ausentes no intake: ' + faltando.join(', '));
}

const soDigitos = (v) => String(v || '').replace(/\D/g, '');

function mascararCpf(cpf) {
  const d = soDigitos(cpf);
  if (d.length !== 11) return '***.***.***-**';
  return '***.***.***-' + d.slice(9);
}

function mascararNome(nome) {
  const partes = String(nome).trim().split(/\s+/).filter(Boolean);
  const primeiro = partes.shift() || '';
  const iniciais = partes.map((p) => p.charAt(0).toUpperCase() + '.');
  return [primeiro].concat(iniciais).join(' ');
}

function sanitizarTexto(txt) {
  return String(txt || '')
    .replace(/\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/g, '[CNPJ]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF]')
    .replace(/[\w.+-]+@[\w-]+\.[\w.]{2,}/g, '[EMAIL]')
    .replace(/\(?\d{2}\)?\s?9?\d{4}-?\d{4}/g, '[TELEFONE]');
}

const agora = new Date();
const carimbo = agora.toISOString().slice(0, 10).replace(/-/g, '');
const sufixo = Math.random().toString(36).slice(2, 8).toUpperCase();

return [{
  json: {
    protocolo: 'JF-' + carimbo + '-' + sufixo,
    recebido_em: agora.toISOString(),
    nome_mascarado: mascararNome(body.nome_cliente),
    cpf_mascarado: mascararCpf(body.cpf),
    descricao_caso: body.descricao_caso,
    descricao_sanitizada: sanitizarTexto(body.descricao_caso),
    origem: body.origem || 'desconhecida',
  },
}];

// Le a resposta do modelo com tolerancia a markdown e a texto extra, normaliza a
// area para uma chave canonica e marca para revisao manual tudo que nao for
// reconhecido, em vez de deixar cair em um canal qualquer sem aviso.
const CANONICAS = {
  trabalhista: 'Trabalhista',
  civel: 'Cível',
  tributario: 'Tributário',
  criminal: 'Criminal',
  consumidor: 'Consumidor',
};

const SINONIMOS = {
  'direito do trabalho': 'trabalhista',
  trabalho: 'trabalhista',
  'direito civil': 'civel',
  civil: 'civel',
  familia: 'civel',
  'direito tributario': 'tributario',
  tributos: 'tributario',
  fiscal: 'tributario',
  'direito penal': 'criminal',
  penal: 'criminal',
  crime: 'criminal',
  'direito do consumidor': 'consumidor',
  consumo: 'consumidor',
  cdc: 'consumidor',
};

const URGENCIAS = ['alta', 'media', 'baixa'];

function normalizar(valor) {
  return String(valor || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .trim();
}

function extrairJson(bruto) {
  const limpo = String(bruto || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const inicio = limpo.indexOf('{');
  const fim = limpo.lastIndexOf('}');
  if (inicio === -1 || fim === -1) {
    throw new Error('sem objeto JSON reconhecivel');
  }
  return JSON.parse(limpo.slice(inicio, fim + 1));
}

const entrada = $('Sanitizar Entrada').first().json;
// A forma da resposta do no de LLM muda entre versoes do n8n: ja veio como
// { message: { content } }, como { content }, e como a resposta crua da API em
// { choices: [...] }. Em vez de adivinhar a versao, varre o objeto e colhe toda
// string que possa conter o JSON pedido. Deriva de versao deixa de quebrar o
// roteamento, que foi o que aconteceu ao migrar de plataforma.
function colherTextos(valor, prof) {
  if (prof > 6 || valor == null) return [];
  if (typeof valor === 'string') return valor.indexOf('{') >= 0 ? [valor] : [];
  if (Array.isArray(valor)) {
    return valor.reduce(function (acc, v) { return acc.concat(colherTextos(v, prof + 1)); }, []);
  }
  if (typeof valor === 'object') {
    // Campos mais provaveis primeiro, para nao depender da ordem das chaves.
    const preferidos = ['content', 'text', 'output', 'message', 'choices', 'data', 'response'];
    const chaves = Object.keys(valor).sort(function (a, b) {
      return preferidos.indexOf(b) - preferidos.indexOf(a);
    });
    return chaves.reduce(function (acc, k) { return acc.concat(colherTextos(valor[k], prof + 1)); }, []);
  }
  return [];
}

// usage tambem muda de lugar; procurar por chave conhecida e mais robusto que
// fixar o caminho. Alimenta a metrica de custo do Bloco 2.
function acharUso(valor, prof) {
  if (prof > 6 || valor == null || typeof valor !== 'object') return null;
  if (valor.prompt_tokens !== undefined || valor.promptTokens !== undefined) return valor;
  for (const k of Object.keys(valor)) {
    const r = acharUso(valor[k], prof + 1);
    if (r) return r;
  }
  return null;
}

const candidatos = colherTextos($json, 0);
const bruto = candidatos.length ? candidatos[0] : '';
const uso = acharUso($json, 0) || {};

let areaChave = null;
let urgencia = 'media';
let revisaoManual = false;
let motivo = '';

try {
  if ($json.error) {
    throw new Error('provedor retornou erro: ' + JSON.stringify($json.error).slice(0, 200));
  }
  let dados = null;
  let ultimoErro = null;
  for (const c of (candidatos.length ? candidatos : [''])) {
    try { dados = extrairJson(c); break; } catch (e) { ultimoErro = e; }
  }
  if (!dados) {
    // Sem historico de execucao (saveDataSuccessExecution: none), a forma do
    // objeto so chega aqui. Sao nomes de chave, nunca conteudo do caso.
    // Este no recebe apenas o retorno do provedor; o texto do caso fica no no
    // anterior e nao passa por aqui. Logo, um trecho do objeto e diagnostico
    // seguro, e e o unico caminho que sobra sem historico de execucao.
    let amostra = '';
    try { amostra = JSON.stringify($json).slice(0, 220); } catch (e) { amostra = '(nao serializavel)'; }
    throw new Error((ultimoErro ? ultimoErro.message : 'sem resposta')
      + ' | recebido: ' + amostra);
  }
  const areaNormalizada = normalizar(dados.area);
  areaChave = CANONICAS[areaNormalizada] ? areaNormalizada : (SINONIMOS[areaNormalizada] || null);

  const urgenciaNormalizada = normalizar(dados.urgencia);
  urgencia = URGENCIAS.indexOf(urgenciaNormalizada) >= 0 ? urgenciaNormalizada : 'media';

  if (!areaChave) {
    revisaoManual = true;
    motivo = 'area nao reconhecida: ' + String(dados.area).slice(0, 60);
  }
} catch (erro) {
  revisaoManual = true;
  motivo = 'falha ao interpretar a classificacao: ' + erro.message;
}

const latencia = Date.now() - new Date(entrada.recebido_em).getTime();

return [{
  json: {
    protocolo: entrada.protocolo,
    recebido_em: entrada.recebido_em,
    latencia_ms: latencia,
    area_chave: areaChave || 'triagem_manual',
    area: areaChave ? CANONICAS[areaChave] : 'Triagem manual',
    urgencia: urgencia,
    revisao_manual: revisaoManual,
    motivo_revisao: motivo,
    nome_mascarado: entrada.nome_mascarado,
    cpf_mascarado: entrada.cpf_mascarado,
    descricao_caso: entrada.descricao_caso,
    origem: entrada.origem,
    modelo: 'gpt-4o-mini',
    tokens_entrada: uso.prompt_tokens !== undefined ? uso.prompt_tokens : (uso.promptTokens || null),
    tokens_saida: uso.completion_tokens !== undefined ? uso.completion_tokens : (uso.completionTokens || null),
  },
}];

